import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        final int MAX = 505;
        int[][] C = new int[MAX][MAX];
        int[] way = new int[MAX];
        int[] sum = new int[MAX];
        int[][] g = new int[MAX][MAX];
        int[][] f = new int[MAX][MAX];

        // Initialize combination array C
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add_mod(C[i - 1][j - 1], C[i - 1][j], mod);
            }
        }

        // Initialize way and sum arrays
        way[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                way[i] = add_mod(way[i], multiply(m + 1, C[i - 1][j], way[j], way[i - j - 1], mod), mod);
                sum[i] = add_mod(sum[i], multiply(triangle_sum(j), way[j], way[i - j - 1], mod), mod);
                int temp = add_mod(multiply(sum[j], way[i - j - 1], mod), multiply(way[j], sum[i - j - 1], mod), mod);
                sum[i] = add_mod(sum[i], multiply(i + 1, temp, C[i - 1][j], mod), mod);
            }
        }

        n += 1;
        f[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; j + k <= m && i + k + 1 <= n; k++) {
                    int val_f = multiply(f[i][j], way[k], mod);
                    f[i + k + 1][j + k] = add_mod(f[i + k + 1][j + k], val_f, mod);
                    int val_g = add_mod(multiply(val_f, sum[k], mod), multiply(g[i][j], way[k], mod), mod);
                    g[i + k + 1][j + k] = add_mod(g[i + k + 1][j + k], val_g, mod);
                }
            }
        }

        System.out.println(g[n][m]);
        sc.close();
    }

    private static int add_mod(int a, int b, int mod) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    private static int multiply(int... args) {
        int mod = args[args.length - 1];
        long res = 1;
        for (int i = 0; i < args.length - 1; i++) {
            res = (res * args[i]) % mod;
        }
        return (int) res;
    }

    private static int triangle_sum(int i) {
        return i * (i + 1) / 2;
    }
}
